#!/usr/bin/env node
// Scans app/prototypes/* and writes two generated (git-ignored) files:
//
//   lib/registry.generated.ts      slug -> metadata + lazy component loader + asset flags
//   lib/public-slugs.generated.ts  list of public slugs (tiny, safe to import from proxy.ts)
//
// Runs automatically from next.config.ts (dev + build) and from `pnpm registry`.
// Never edit the generated files by hand.

import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const PROTOTYPES_DIR = path.join(ROOT, "app", "prototypes");
const PUBLIC_DIR = path.join(ROOT, "public");
const REGISTRY_FILE = path.join(ROOT, "lib", "registry.generated.ts");
const PUBLIC_SLUGS_FILE = path.join(ROOT, "lib", "public-slugs.generated.ts");

const SLUG_RE = /^[a-z0-9]+(?:-[a-z0-9]+)*$/;

function exists(rel) {
  return fs.existsSync(path.join(PUBLIC_DIR, rel));
}

export function discoverPrototypes() {
  if (!fs.existsSync(PROTOTYPES_DIR)) return [];
  const entries = fs.readdirSync(PROTOTYPES_DIR, { withFileTypes: true });
  const found = [];
  for (const entry of entries) {
    if (!entry.isDirectory()) continue;
    const slug = entry.name;
    // Skip dynamic segments ([slug]), route groups ((x)), private folders (_x).
    if (!SLUG_RE.test(slug)) continue;
    const dir = path.join(PROTOTYPES_DIR, slug);
    const metaPath = path.join(dir, "metadata.json");
    const pagePath = path.join(dir, "page.tsx");
    if (!fs.existsSync(metaPath) || !fs.existsSync(pagePath)) {
      console.warn(`[registry] skipping "${slug}": needs page.tsx and metadata.json`);
      continue;
    }
    let meta;
    try {
      meta = JSON.parse(fs.readFileSync(metaPath, "utf8"));
    } catch (err) {
      console.warn(`[registry] skipping "${slug}": invalid metadata.json (${err.message})`);
      continue;
    }
    found.push({
      slug,
      public: meta.public === true,
      thumbnail: exists(`thumbnails/${slug}-light.jpg`) && exists(`thumbnails/${slug}-dark.jpg`),
      ogImage: exists(`og/${slug}.png`),
      ogVideo: exists(`og/${slug}.mp4`),
    });
  }
  return found.sort((a, b) => a.slug.localeCompare(b.slug));
}

function writeIfChanged(file, contents) {
  const prev = fs.existsSync(file) ? fs.readFileSync(file, "utf8") : null;
  if (prev === contents) return false;
  fs.writeFileSync(file, contents);
  return true;
}

export function generateRegistry({ quiet = false } = {}) {
  const protos = discoverPrototypes();
  const header = "// AUTO-GENERATED by scripts/generate-registry.mjs. Do not edit.\n";

  const imports = protos
    .map((p, i) => `import meta${i} from "@/app/prototypes/${p.slug}/metadata.json";`)
    .join("\n");
  const rows = protos
    .map(
      (p, i) => `  {
    slug: ${JSON.stringify(p.slug)},
    metadata: meta${i} as RawMetadata,
    assets: { thumbnail: ${p.thumbnail}, ogImage: ${p.ogImage}, ogVideo: ${p.ogVideo} },
    load: () => import("@/app/prototypes/${p.slug}/page"),
  },`
    )
    .join("\n");

  const registry = `${header}import type { RegistryEntry, RawMetadata } from "./prototype-types";
${imports}

export const registry: RegistryEntry[] = [
${rows}
];
`;

  const publicSlugs = `${header}export const publicSlugs: readonly string[] = ${JSON.stringify(
    protos.filter((p) => p.public).map((p) => p.slug)
  )};
`;

  const changed = [writeIfChanged(REGISTRY_FILE, registry), writeIfChanged(PUBLIC_SLUGS_FILE, publicSlugs)];
  if (!quiet && changed.some(Boolean)) {
    console.log(`[registry] ${protos.length} prototype(s): ${protos.map((p) => p.slug).join(", ") || "none"}`);
  }
  return protos;
}

// CLI entry
if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  generateRegistry();
}
